              "c": "<span class=\"kw\">Menkes病はATP7A遺伝子異常によるX連鎖性の銅輸送異常症で、腸管からの銅吸収・細胞内輸送が障害され銅依存性酵素（リジルオキシダーゼ、シトクロムC酸化酵素、チロシナーゼ等）の活性が低下する</span>。血清セルロプラスミン（銅結合蛋白）は<span class=\"kw\">本疾患で低値となる代表的な検査所見</span>。銅依存性酵素の活性低下により<span class=\"kw\">毛髪のケラチン架橋形成に必要なリジルオキシダーゼの機能不全から、特徴的な捻転毛・まばらで色調の乏しい\"kinky hair（捻れ髪）\"を来す。これに加え、進行性の筋緊張低下、発達遅滞、けいれん、易感染性（好中球機能への影響）、皮膚の弛緩等を呈する</span>。<span class=\"kw4\">a肝脾腫はGaucher病等のリソソーム病でより典型的、b頭囲拡大はMenkes病ではむしろ進行性の小頭傾向を呈することが多い、d Kayser-Fleischer輪は銅が\"過剰\"に蓄積するWilson病でみられる所見であり、銅が\"欠乏\"するMenkes病とは病態が正反対（紛らわしい引っかけ選択肢）、e桜実紅斑〈cherry-red spot〉はTay-Sachs病・Niemann-Pick病等のスフィンゴリピド蓄積症でみられる眼底所見でMenkes病には特徴的でない</span>。"
