              "c": "<span class=\"kw\">本例は尿所見・腎/膀胱超音波検査に異常を認めず、日中の失禁もない一次性単一症候性夜尿症であり、多くは膀胱容量やホルモン（夜間の抗利尿ホルモン分泌）の発達的な未成熟が背景にあり、成長とともに自然軽快することが多い良性の病態</span>。標準的な生活指導（ウロセラピー）は<span class=\"kw\">①就寝前に完全に排尿させる、②夕方以降の水分摂取を控え日中（特に午前〜午後早い時間）に多めに摂る、③睡眠中の身体の冷えを防ぐ、④おねしょをしても叱らず心理的な負担を与えない</span>という4点が基本となる。一方、<span class=\"kw\">夜間に決まった時間に強制的に起こして排尿させること（scheduled waking）は、睡眠の質を損なう割に夜尿症そのものの治癒を促進する効果が確立されておらず、標準的な初期指導としては推奨されない（これに対し、夜尿を感知して音・振動で child を目覚めさせる\"アラーム療法\"は専門的な治療法として別に確立されている）</span>。<span class=\"kw4\">a・b・c・dはいずれも夜尿症の標準的な生活指導として適切</span>。"
