          "qt": "※ MEC分類では内科系・血液。<br/><br/>6歳の女児。腹痛と血便を主訴に来院した。昨日から腹痛を訴え、本日血便がみられたため、母親に連れられて受診した。2日前に近所の店で焼肉を食べたという。意識は清明。体重20kg。体温37.5℃。脈拍90/分、整。血圧110/60mmHg。呼吸数20/分。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦で臍周囲に軽度圧痛を認める。肝・脾を触知しない。腸雑音は亢進している。尿所見：蛋白（－）、糖（－）、ケトン体2＋、潜血（－）。血液所見：赤血球420万、Hb 13.2g/dL、Ht 42％、白血球12,300（桿状核好中球30％、分葉核好中球55％、好酸球1％、好塩基球1％、単球6％、リンパ球7％）、血小板21万、PT-INR 1.2（基準0.9〜1.1）、APTT 32秒（基準対照32.2）。血液生化学所見：総蛋白7.5g/dL、アルブミン3.9g/dL、総ビリルビン0.9mg/dL、AST 28U/L、ALT 16U/L、LD 300U/L（基準175〜320）、CK 60U/L（基準46〜230）、尿素窒素20mg/dL、クレアチニン0.6mg/dL、血糖98mg/dL、Na 131mEq/L、K 4.4mEq/L、Cl 97mEq/L。CRP 4.5mg/dL。便中ベロトキシン陽性であった。<br/><br/><strong>この患者で溶血性尿毒症症候群〈HUS〉の発症に注意するために有用な血液検査項目はどれか。3つ選べ。</strong>",
