              "cls": "ep",
              "h": "🩸 HUSの3主徴とモニタリング項目",
              "c": "<span class=\"kw\">便中ベロトキシン（志賀毒素）陽性は腸管出血性大腸菌〈EHEC、O157等〉感染を裏付ける所見で、この感染の重篤な続発症として溶血性尿毒症症候群〈HUS〉があり、下痢・血便の発症から数日〜1週間程度でHUSを発症することが多い</span>。HUSは<span class=\"kw\">①微小血管障害性溶血性貧血（破砕赤血球を伴う溶血）、②血小板減少、③急性腎障害という3主徴を特徴とする</span>ため、これらを反映する検査項目を経時的にフォローする必要がある：<span class=\"kw\">赤血球数（Hb・Htも含め溶血性貧血の進行を評価）、血小板数（消費性の血小板減少を評価）、クレアチニン（腎機能障害の進行を評価）</span>。<span class=\"kw4\">aCKは横紋筋融解症等の評価に用いるがHUSの主徴ではない、bCRPは炎症の程度を反映する非特異的マーカーでHUSの3主徴を直接反映するものではない</span>。"
