              "h": "🖼️ 全身型JIAの5主徴とMRI所見",
              "c": "<span class=\"kw\">全身型若年性特発性関節炎（全身型JIA、小児Still病）は、①弛張熱（1日のうち高熱と解熱を繰り返すスパイク状パターン）、②発熱時に一致して出現し解熱すると消退する淡紅色（サーモンピンク色）の一過性皮疹、③関節炎、④リンパ節腫大、⑤肝脾腫という5主徴を特徴とする</span>。MRIでは<span class=\"kw\">罹患関節（本例では左膝）の滑膜肥厚・関節液貯留・造影による滑膜の増強効果</span>が確認され、関節炎の存在を裏付ける。検査所見では<span class=\"kw\">MMP-3（滑膜由来の酵素で滑膜炎の活動性を反映）の著明高値、RF・抗核抗体はいずれも陰性であることが多い（全身型JIAは血清反応陰性）</span>のが特徴。<span class=\"kw4\">a川崎病は5日以上の発熱と5主要症状（結膜充血・口唇口腔所見・発疹・四肢末端変化・頸部リンパ節腫大）を特徴とし、本例のような弛張熱パターン・著明な肝脾腫・関節炎主体の経過とは異なる、bIgA血管炎は触知可能な紫斑（本例は紅斑であり性状が異なる）・腹痛を伴うことが多く肝脾腫は来さない、cリウマチ熱は先行する溶連菌感染歴と多関節が移動性に侵される多関節炎（本例は単関節）が典型、d化膿性関節炎は通常単関節で急速に増悪し高度の関節可動域制限・激痛を伴うが本例は可動域制限がないという点で非典型</span>。"
