              "c": "<span class=\"kw\">川崎病は急性期に治療（IVIG等）が行われなかった時代（本例は45歳であり乳幼児期は治療体制が現在ほど整っていなかった可能性がある）や、治療しても十分な反応が得られなかった症例で、巨大な冠動脈瘤を形成することがある</span>。このような<span class=\"kw\">巨大冠動脈瘤は数年〜数十年の経過で瘤内に血栓が形成されたり、瘤の入口部・出口部に狭窄性病変（内膜肥厚・石灰化）が生じたりすることがあり、中年期以降に虚血性心疾患（狭心症・心筋梗塞）として顕在化する</span>ことが知られている。右冠動脈造影像では<span class=\"kw\">瘤状拡張とそれに続く狭窄、あるいは石灰化を伴う瘤形成といった川崎病後遺症に特徴的な形態</span>が想定される。本例の<span class=\"kw\">3歳時の「発熱と皮疹」での入院歴は詳細不明とされているが、年齢・症状のパターンから川崎病であった可能性が極めて高く、その後の定期健診で異常を指摘されなかったのは、必ずしも定期的な心エコー等による冠動脈のフォローが行われていなかったことを示唆する</span>。<span class=\"kw4\">bBuerger病は喫煙との関連が強い疾患で本例に喫煙歴はない、cHigh安動脈炎は若年女性の大動脈・主要分枝の炎症性疾患で通常は大動脈本幹〜近位分枝が主座、dMarfan症候群は大動脈基部拡張・解離が典型で本例のような限局性の冠動脈病変の説明としては非典型、eたこつぼ心筋症は冠動脈造影上は有意狭窄を認めないことが特徴で、本例の冠動脈造影で病変が確認されている点と矛盾する</span>。"
