              "c": "<span class=\"kw\">重症複合免疫不全症〈SCID〉はT細胞（多くはB細胞・NK細胞も）の発生・機能が高度に障害される原発性免疫不全症の中で最重症の病型であり、母体からの移行抗体が減衰する生後数か月以内から重症の細菌・ウイルス・真菌・日和見感染症を繰り返し、慢性の下痢・肺炎等を背景に体重増加不良（Failure to thrive）を来す</span>。無治療では多くが乳児期に致死的となるため、造血幹細胞移植等の早期治療介入が必須。<span class=\"kw4\">a T細胞・B細胞の産生・機能が高度に障害されるため、感染に対する反応としてのリンパ節腫大はむしろ乏しく、胸腺・扁桃・リンパ節が低形成となることが特徴（「全身のリンパ節が腫大する」は誤り）、bウイルス（特に水痘・麻疹・CMV等）に対する免疫も高度に障害され重症化しやすい（「保たれる」は誤り）、c遺伝形式は最も頻度の高い型（X連鎖性SCID、IL2RG遺伝子異常）を含め多くがX連鎖劣性または常染色体劣性遺伝であり、顕性（優性）遺伝ではない、d B細胞機能も障害されるため血清免疫グロブリンは低下することが多く正常範囲ではない</span>。"
