              "c": "<span class=\"kw\">IgA血管炎は小血管を主体とする血管炎で、皮膚では真皮の細小血管にIgAを主体とした免疫複合体が沈着し、重力の影響を受けやすい下肢（特に足背・下腿）に左右対称性の触知可能な紫斑を来す</span>。右足の皮膚所見では<span class=\"kw\">隆起を触れる紫紅色〜暗赤色の斑状皮疹が足背に集簇する所見</span>が想定される。本例は<span class=\"kw\">皮疹（紫斑）＋足関節痛＋腹痛（臍周囲圧痛）という三徴をすべて満たしており、IgA血管炎の診断に矛盾しない</span>。<span class=\"kw4\">a川崎病は5日以上の発熱を伴う全身性の血管炎で本例のような限局した紫斑・関節痛・腹痛のパターンとは異なる、b血友病は関節内出血（血腫）を来すが皮膚に触知可能な紫斑としての皮疹は通常主体でない、d若年性特発性関節炎は関節炎が主体で本例のような紫斑を伴う皮疹は典型像でない、e血栓性微小血管障害症（HUS等）は溶血性貧血・血小板減少・急性腎障害を来す全身性疾患で、本例のような限局した皮疹・関節痛・腹痛のみのパターンとは異なる</span>。"
