              "c": "<span class=\"kw\">本例はQ350と同じくvon Willebrand因子の欠乏を示唆する検査パターン（出血時間延長＋APTT延長）を呈しているが、加えて「関節内出血や筋肉内出血の既往がない」という情報が明示的に与えられている点が鑑別の決め手となる</span>。<span class=\"kw\">血友病（第Ⅷ・第Ⅸ因子欠乏）は深部出血（関節内出血・筋肉内出血）を来しやすいのに対し、von Willebrand病は一次止血（血小板の血管内皮への接着）の障害が主体であるため、鼻出血・歯肉出血等の粘膜出血が主体で関節内出血は通常来さない</span>という臨床的な違いがあり、本例の経過はvWDを強く支持する。<span class=\"kw4\">a血友病Aは深部出血（関節内・筋肉内出血）を特徴とし、また出血時間は正常（本例は延長）であるため合致しない、cビタミンK欠乏症は主にPTが延長する（本例のPTは正常）、dIgA血管炎は触知可能な紫斑を伴う血管炎で、出血時間・APTTの延長という凝固検査異常のパターンとは異なる、e遺伝性出血性末梢血管拡張症〈Osler病〉は皮膚・粘膜の毛細血管拡張病変が特徴的な所見として存在するはずだが本例では体表に出血斑を認めないと明記されている</span>。"
