              "c": "<span class=\"kw\">Kasabach-Merritt症候群は、Kaposi型血管内皮腫や房状血管腫といった特殊な血管性腫瘍内に、血小板を中心とした血液成分が捕捉・消費されることで、著明な血小板減少と消費性凝固障害（Dダイマー高値、フィブリノゲン低下等）を来す病態</span>。大腿部の写真では<span class=\"kw\">境界不明瞭で皮膚から隆起した暗紫紅色〜紫色調の弾性硬な腫瘤（腫瘍内への血液貯留を反映）</span>が想定され、出生時から存在した血管性病変が急速に増大するという経過に一致する。<span class=\"kw\">腫瘍が急速に増大する時期に一致して血小板が腫瘍内に捕捉・消費され、著明な血小板減少（本例4万）とDダイマー著明高値（13.8）という消費性凝固障害の所見が顕在化</span>し、活気不良もこの全身性の血液学的異常を反映する。<span class=\"kw4\">bOsler病（遺伝性出血性毛細血管拡張症）は多発する小さな毛細血管拡張病変が特徴で、単一の急速増大する腫瘤という所見とは異なる、cSturge-Weber症候群は顔面のポートワイン母斑・軟膜血管腫・けいれんが特徴で四肢の腫瘤とは異なる、dvon Recklinghausen病（神経線維腫症1型）はカフェオレ斑・神経線維腫が特徴で血小板減少・消費性凝固障害は来さない、eWiskott-Aldrich症候群は湿疹・血小板減少・易感染性を三徴とするが、本例のような急速増大する限局性の血管性腫瘤は伴わない</span>。"
