              "c": "<span class=\"kw\">ピーナッツ等の食物（特に脂肪分を含む豆類は気道粘膜への刺激性が強い）は乳幼児の気道異物として頻度が高く、歩行中・遊びながらの摂食（むせ込みへの対応が遅れやすい状況）が誘因となりやすい</span>。気道異物が気管支内に嵌頓すると<span class=\"kw\">ball-valve機構（吸気時は空気が末梢へ流入できるが呼気時には異物が弁のように働き空気の排出が妨げられる）により、患側肺の含気量が呼気時に特に増加する（過膨張・air trapping）</span>ため、<span class=\"kw\">吸気時と呼気時の胸部エックス線写真を撮り比べることで、呼気時に患側肺の透過性亢進・縦隔の健側への偏位が目立つという所見が異物の存在部位を示唆する</span>。診断がついた（あるいは強く疑われる）気道異物に対する<span class=\"kw\">根本的な治療は気管支内視鏡（硬性気管支鏡または軟性気管支鏡）による直達的な異物摘出</span>であり、まず行うべき処置となる。<span class=\"kw4\">a酸素投与は低酸素があれば併用するが根本治療にならない、b開胸手術は気管支鏡での摘出が奏効しない特殊な場合の最終手段であり第一選択でない、c抗菌薬静脈内投与は二次性の閉塞性肺炎を合併した場合に検討するが本例でまず行う処置ではない、d Heimlich法は完全気道閉塞で窒息が切迫している急性の場面で行う救命手技であり、本例のようにSpO2が保たれ会話・咳嗽が可能な安定した状態（部分的な閉塞）には適応とならない</span>。"
