              "c": "<span class=\"kw\">食道異物にはさまざまな種類があるが、その多くは物理的な閉塞・粘膜損傷にとどまり、24時間程度は比較的安全に経過観察・待機的な摘出が可能なことが多い。これに対しボタン電池は、単なる物理的異物ではなく電気化学的な組織傷害（水酸化物イオンによる液化壊死）を引き起こすため、停留からわずか2時間程度で組織傷害が始まり、放置すれば食道穿孔・気管食道瘻・致死的な大血管損傷にまで進行しうる</span>。この<span class=\"kw\">化学熱傷という特殊な傷害機序のため、ボタン電池は食道異物の中で突出して緊急性が高く、発見・診断され次第、症状の有無を問わず直ちに内視鏡的摘出を行う</span>必要がある（Q363参照）。<span class=\"kw4\">a魚骨は粘膜への穿刺・裂傷のリスクはあるが化学的傷害はなく、比較的待機的な対応が可能なことが多い、b硬貨は不活性で通常は数日単位で自然排出を待つ経過観察が可能（食道内停留が長期化する場合は摘出を検討）、c歯牙も不活性な異物で緊急性は低い、ePTP包装は鋭利な角による粘膜損傷・穿孔のリスクはあるが化学的傷害は伴わずボタン電池ほどの緊急性はない</span>。"
